/**
 * PARITY GATE — the TypeScript engine must reproduce `engine/position.py`
 * exactly, frame for frame.
 *
 * The fixture `engine/parity_frames.json` is generated by
 * `python -m pipeline.parity_frames` from the same database the export comes
 * from. 6,000 sampled (trip, instant) pairs, deliberately covering midnight
 * tails, dwell edges, untimed rows and bypassed waypoints.
 *
 * Tolerances (from docs/DATA_SCHEMA.md §3 and AGENTS.md):
 *   position   <= 1 m      (haversine between expected and actual)
 *   s_m        <= 1 m
 *   speed      <= 0.2 km/h
 *   status / from / to / next_stop / next_stop_time   exact
 *
 * ZERO tolerated failures. A mismatch is a port bug: fix the port, never widen
 * the tolerance.
 */
import { beforeAll, describe, expect, it } from "vitest";
import { haversineM } from "./geometry";
import { buildSnapshot } from "./load";
import { positionsAt } from "./position";
import { midnightEpochMs, parseIsoDate } from "./time";
import type { Policy, ScheduleSnapshot } from "./types";
import { readExportedBundle, readParityFixture, type ParityFixture } from "./testUtils";

const POSITION_TOLERANCE_M = 1;
const S_M_TOLERANCE_M = 1;
const SPEED_TOLERANCE_KMH = 0.2;

interface Mismatch {
  readonly index: number;
  readonly tripId: string;
  readonly tS: number;
  readonly field: string;
  readonly expected: unknown;
  readonly actual: unknown;
  readonly detail?: string | undefined;
}

let snapshot: ScheduleSnapshot;
let fixture: ParityFixture;
let mismatches: Mismatch[];
let compared: number;

beforeAll(async () => {
  const [raw, loaded] = await Promise.all([readExportedBundle(), readParityFixture()]);
  snapshot = buildSnapshot(raw);
  fixture = loaded;

  const policy: Policy = fixture.policy;
  const serviceMidnight = midnightEpochMs(parseIsoDate(fixture.service_date));

  // One positionsAt call per distinct instant, then pick our trips out — the
  // same shape the Python generator used.
  const byInstant = new Map<number, Array<{ index: number; tripId: string }>>();
  fixture.frames.forEach((frame, index) => {
    const bucket = byInstant.get(frame.t_s) ?? [];
    bucket.push({ index, tripId: frame.trip_id });
    byInstant.set(frame.t_s, bucket);
  });

  mismatches = [];
  compared = 0;

  for (const [tS, wanted] of byInstant) {
    const positions = positionsAt(snapshot, serviceMidnight + tS * 1000, policy);
    const byTrip = new Map(positions.map((position) => [position.tripId, position]));

    for (const { index, tripId } of wanted) {
      const frame = fixture.frames[index]!;
      const actual = byTrip.get(tripId);
      compared += 1;
      const push = (field: string, expected: unknown, value: unknown, detail?: string) => {
        mismatches.push({ index, tripId, tS, field, expected, actual: value, detail });
      };

      if (!frame.present) {
        if (actual !== undefined) push("present", false, true);
        continue;
      }
      if (actual === undefined) {
        push("present", true, false);
        continue;
      }

      // --- exact fields ---
      if (actual.status !== frame.status) push("status", frame.status, actual.status);
      if (actual.fromCode !== frame.from) push("from", frame.from, actual.fromCode);
      if (actual.toCode !== frame.to) push("to", frame.to, actual.toCode);
      if (actual.nextStopCode !== frame.next_stop) {
        push("next_stop", frame.next_stop, actual.nextStopCode);
      }
      if (actual.nextStopTime !== frame.next_stop_time) {
        push("next_stop_time", frame.next_stop_time, actual.nextStopTime);
      }

      // --- metric tolerances ---
      const expectedPoint = { lat: frame.lat!, lon: frame.lon! };
      const actualPoint = { lat: actual.lat, lon: actual.lon };
      const errorM = haversineM(expectedPoint, actualPoint);
      if (!(errorM <= POSITION_TOLERANCE_M)) {
        push("position", expectedPoint, actualPoint, `${errorM.toFixed(3)} m`);
      }

      const sError = Math.abs(actual.sM - frame.s_m!);
      if (!(sError <= S_M_TOLERANCE_M)) {
        push("s_m", frame.s_m, actual.sM, `${sError.toFixed(3)} m`);
      }

      const speedError = Math.abs(actual.speedKmh - frame.speed_kmh!);
      if (!(speedError <= SPEED_TOLERANCE_KMH)) {
        push("speed_kmh", frame.speed_kmh, actual.speedKmh, `${speedError.toFixed(3)} km/h`);
      }
    }
  }
});

function report(entries: readonly Mismatch[]): string {
  const head = entries.slice(0, 15).map((entry) => {
    const detail = entry.detail ? ` (${entry.detail})` : "";
    return (
      `  #${entry.index} ${entry.tripId} t=${entry.tS}s ${entry.field}: ` +
      `expected ${JSON.stringify(entry.expected)}, got ${JSON.stringify(entry.actual)}${detail}`
    );
  });
  return `${entries.length} mismatch(es):\n${head.join("\n")}`;
}

describe("parity with engine/position.py", () => {
  it("loads the fixture the gate is defined against", () => {
    expect(fixture.count).toBe(6000);
    expect(fixture.frames).toHaveLength(6000);
    expect(fixture.trips_sampled).toBe(625);
    expect(snapshot.trips).toHaveLength(625);
  });

  it("compares every sampled frame", () => {
    expect(compared).toBe(6000);
  });

  it("reproduces all 6,000 frames with zero failures", () => {
    // Printed on purpose: the gate's evidence should be visible in CI logs, not
    // inferred from a green tick.
    console.log(
      `parity: ${compared - mismatches.length}/${compared} frames matched, ` +
        `${mismatches.length} failure(s)`,
    );
    expect(mismatches, report(mismatches)).toHaveLength(0);
  });

  it("covers the deliberate edge cases the fixture was built for", () => {
    const sampledTrips = new Set(fixture.frames.map((frame) => frame.trip_id));
    const trips = snapshot.trips.filter((trip) => sampledTrips.has(trip.tripId));

    // midnight tails, untimed markers and bypassed waypoints must all be present
    expect(trips.some((trip) => trip.lastAbs > 86_400)).toBe(true);
    expect(trips.some((trip) => trip.hasUntimedMarkers)).toBe(true);
    expect(trips.some((trip) => trip.hasBypassedWaypoints)).toBe(true);
    // both statuses occur, so the gate is not only exercising dwells
    const statuses = new Set(fixture.frames.map((frame) => frame.status));
    expect(statuses.has("at_station")).toBe(true);
    expect(statuses.has("running")).toBe(true);
  });
});
